&lt;p style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;font-family: tahoma, arial, helvetica, sans-serif; color: rgb(126, 140, 141);&quot;&gt;&lt;em&gt;Privacy Statement&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
